<?php defined('BASEPATH') OR exit('No direct script access allowed');class Gift_cards extends MY_Controller{private $c;function __construct(){parent::__construct();$this->c=$this->require_auth();if(!$this->c)return;$this->load->model('Gift_card_model','gc');}function dashboard(){return$this->respond($this->gc->dashboard($this->c['organizationId']));}function cards($id=NULL,$action=NULL){$o=$this->c['organizationId'];$m=$this->input->method(TRUE);if(!$id&&$m==='GET')return$this->respond($this->gc->cards($o,$this->input->get('status')));if(!$id){$d=$this->body();$types=array('physical','digital','virtual','one-time','reloadable','promotional','enterprise','corporate-reward','employee-incentive','educational');if(!isset($d['type'],$d['amount'],$d['currency'])||!in_array($d['type'],$types,TRUE)||(float)$d['amount']<=0||strlen($d['currency'])!==3||isset($d['pin'])&&(strlen($d['pin'])<4||strlen($d['pin'])>8))return$this->fail('VALIDATION_ERROR','Invalid gift card input',422);return$this->respond($this->gc->issue($o,$this->c['sub'],$d),201);}if(!$action){$r=$this->gc->card($o,$id);return$r?$this->respond($r):$this->fail('NOT_FOUND','Card not found',404);}if(!in_array($action,array('activate','reload','redeem','expire','freeze','unfreeze','apply-invoice'),TRUE))return$this->fail('NOT_FOUND','Gift card action not found',404);$d=$this->body();if(in_array($action,array('reload','redeem'),TRUE)&&(!isset($d['amount'])||(float)$d['amount']<=0))return$this->fail('VALIDATION_ERROR','Positive amount required',422);if($action==='freeze'&&strlen(trim($d['reason']??''))<3)return$this->fail('VALIDATION_ERROR','Freeze reason required',422);if($action==='activate')list($r,$e)=$this->gc->activate($o,$id,$d['pin']??NULL);elseif($action==='reload')list($r,$e)=$this->gc->reload($o,$id,$d['amount']);elseif($action==='redeem')list($r,$e)=$this->gc->redeem($o,$id,$d['amount'],$d['pin']??NULL,$d['orderId']??NULL);elseif($action==='apply-invoice')list($r,$e)=$this->gc->apply_invoice($o,$id,$d['invoiceId']??'',$d['pin']??NULL,$d['amount']??NULL);else list($r,$e)=$this->gc->state($o,$id,$action,$d['reason']??NULL);return$e?$this->fail($e,$this->error_message($e),$e==='NOT_FOUND'||$e==='INVOICE_NOT_FOUND'?404:409):$this->respond($r);}function transactions(){return$this->respond($this->gc->transactions($this->c['organizationId'],$this->input->get('cardId')));}function fraud($id=NULL){$o=$this->c['organizationId'];if(!$id){$q=$this->input->get('resolved');return$this->respond($this->gc->fraud($o,$q===NULL?NULL:$q==='true'));}$r=$this->gc->resolve_flag($o,$id,$this->c['sub']);return$r?$this->respond($r):$this->fail('NOT_FOUND','Fraud flag not found',404);}function loyalty(){return$this->respond($this->gc->loyalty($this->c['organizationId']));}function agents(){return$this->respond(array(array('id'=>'gc-agent-spend','name'=>'Spending Analysis Agent','domain'=>'gift-cards','role'=>'Analyze stored spending patterns','disclaimer'=>'Informational only; not financial advice'),array('id'=>'gc-agent-rec','name'=>'Gift Recommendation Agent','domain'=>'gift-cards','role'=>'Recommend gift amounts and types','disclaimer'=>'Suggestions only'),array('id'=>'gc-agent-forecast','name'=>'Revenue Forecast Agent','domain'=>'gift-cards','role'=>'Forecast revenue and redemption','disclaimer'=>'Forecast is not a guarantee'),array('id'=>'gc-agent-loyalty','name'=>'Loyalty Optimization Agent','domain'=>'gift-cards','role'=>'Suggest loyalty tuning','disclaimer'=>'Human approval required')));}function payment_method(){return$this->respond(array('id'=>'wmpc-gift-cards','kind'=>'gift-card','name'=>'WMPC Gift Cards','capabilities'=>array('redeem','balance-inquiry'),'currencies'=>array('USD','NGN','EUR','GBP','JPY','CNY'),'version'=>'0.82.0','registeredAt'=>date('c')));}private function error_message($e){$m=array('BAD_PIN'=>'Invalid PIN','INVALID_STATE'=>'Card state does not permit this action','EXPIRED'=>'Card expired','INSUFFICIENT_FUNDS'=>'Insufficient balance','CURRENCY_MISMATCH'=>'Gift card currency does not match invoice','INVALID_AMOUNT'=>'Invalid amount','INVOICE_NOT_FOUND'=>'Invoice not found in organization');return$m[$e]??'Gift card operation failed';}}
